'use strict';
// Service worker for the GATE CS Archive. Generated by scripts/build_site.py; __CORE_VERSION__ changes whenever the core files do.
// Three caches: CORE (the shell, replaced on every deploy), PACKS (subjects and papers a person chose to save on the
// Offline page; only that page adds or removes entries) and RUNTIME (pages and images seen while browsing, cleared on every deploy).
const CORE = 'gate-core-__CORE_VERSION__', PACKS = 'gate-packs', RUNTIME = 'gate-runtime';
const scope = self.registration.scope;

self.addEventListener('install', event => event.waitUntil((async () => {
  const core = await (await fetch(new URL('offline/core.json', scope), {cache: 'no-store'})).json();
  const cache = await caches.open(CORE);
  await Promise.all(Object.keys(core.files).map(async path => {
    const url = new URL(path, scope), response = await fetch(url, {cache: 'reload'});
    if (!response.ok) throw Error('Could not cache ' + path);
    await cache.put(url, response);
  }));
  await self.skipWaiting();
})()));

self.addEventListener('activate', event => event.waitUntil((async () => {
  for (const name of await caches.keys()) {
    if ((name.startsWith('gate-core-') && name !== CORE) || name === RUNTIME) await caches.delete(name);
  }
  await self.clients.claim();
})()));

const lookup = request => caches.match(request, {ignoreSearch: true});

async function store(request, response) {
  if (!response.ok || response.redirected || response.type !== 'basic') return;
  const packs = await caches.open(PACKS);
  // A page that is part of a saved pack is refreshed in place, so the saved copy never goes stale while online.
  const cache = await packs.match(request, {ignoreSearch: true}) ? packs : await caches.open(RUNTIME);
  try { await cache.put(request, response.clone()); } catch { /* storage full: keep serving from the network */ }
}

function offlinePage() {
  const link = (path, text) => '<a href="' + new URL(path, scope).href + '">' + text + '</a>';
  return new Response('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Not saved for offline use · GATE CS Archive</title>' +
    '<style>:root{color-scheme:light dark}body{font-family:system-ui,sans-serif;line-height:1.6;max-width:36rem;margin:15vh auto;padding:0 20px}a{color:inherit}</style></head><body>' +
    '<h1>This page isn’t saved on this device.</h1><p>You are offline, and this page was not saved or opened before. Subjects and papers you saved still work.</p>' +
    '<p>' + link('offline/', 'See what is saved') + ' · ' + link('', 'Home') + '</p></body></html>',
    {status: 503, headers: {'Content-Type': 'text/html; charset=utf-8'}});
}

async function networkFirst(event) {
  const request = event.request, cached = await lookup(request);
  try {
    // With a saved copy in hand, do not make a reader on a weak signal wait more than a few seconds.
    const network = fetch(request);
    const response = await (cached ? Promise.race([network, new Promise((_, reject) => setTimeout(reject, 4000))]) : network);
    event.waitUntil(store(request, response.clone()));
    return response;
  } catch {
    return cached || (request.mode === 'navigate' ? offlinePage() : Response.error());
  }
}

async function cacheFirst(event) {
  const cached = await lookup(event.request);
  if (cached) return cached;
  const response = await fetch(event.request);
  event.waitUntil(store(event.request, response.clone()));
  return response;
}

async function staleWhileRevalidate(event) {
  const cached = await lookup(event.request);
  const refresh = fetch(event.request).then(response => { event.waitUntil(store(event.request, response.clone())); return response; });
  if (!cached) return refresh;
  event.waitUntil(refresh.catch(() => {}));
  return cached;
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET' || !request.url.startsWith(scope)) return;
  const path = request.url.slice(scope.length).split(/[?#]/)[0];
  // Large downloads, the chunked search index and the offline manifests always come from the network.
  if (path === 'sw.js' || /^(pdf|pagefind)\//.test(path) || /^offline\/.*\.json$/.test(path) || request.headers.has('range')) return;
  if (path.startsWith('assets/questions/')) event.respondWith(cacheFirst(event));
  else if (path.startsWith('assets/')) event.respondWith(staleWhileRevalidate(event));
  else event.respondWith(networkFirst(event));
});
